SELECT channel, ROUND(AVG(retained)::numeric,4) AS retention_90
FROM (
  SELECT user.channel AS channel, user.signup_date,
    CASE WHEN EXISTS (
      SELECT 1 FROM activity a WHERE a.user_id = user.user_id AND a.active_date = user.signup_date + INTERVAL '90 days'
    ) THEN 1 ELSE 0 END AS retained
  FROM "user"
) t
GROUP BY channel
ORDER BY retention_90 DESC;

SELECT channel, ROUND(AVG(retained)::numeric,4) AS retention_90
FROM (
  SELECT u.channel AS channel, u.signup_date,
    CASE WHEN EXISTS (
      SELECT 1 FROM fct_activity a WHERE a.user_id = u.user_id AND a.active_date = u.signup_date + 90
    ) THEN 1 ELSE 0 END AS retained
  FROM dim_users u
) t
GROUP BY channel
ORDER BY retention_90 DESC;

SELECT channel, ROUND(AVG(retention_90)::numeric,4) AS retention_90
FROM (
  SELECT channel, signup_date, retained::int AS retention_90
  FROM (
    SELECT channel, signup_date, CASE WHEN EXISTS(
      SELECT 1 FROM fct_user_days d WHERE d.user_id=u.user_id AND d.active_date = u.signup_date + 90
    ) THEN 1 ELSE 0 END AS retained
    FROM dim_users u
  ) s
) t
GROUP BY channel
ORDER BY retention_90 DESC;
